// One stage of a shift register, with the option to shift in a new value
// at the same time, or to load a new value independent of shifting.
module TopModule(input  clk,
                 input  w,
                 input  R,
                 input  E,
                 input  L,
                 output reg Q);
    reg [1:0] sel;
    always @(posedge clk) begin
        case (sel)
            2'b00: Q <= Q;
            2'b01: Q <= w;
            2'b10: Q <= R;
            2'b11: Q <= R;
        endcase
        if (E) sel <= 2'b01;
        if (L) sel <= 2'b10;
    end
endmodule

